using AldaJoyeros.Mappings;
using AldaJoyeros.DTOs;
using AldaJoyeros.Entities;
using AldaJoyeros.Models.MongoDB;
using MongoDB.Bson;
using MongoDB.Bson.Serialization;
using MimeKit;
var mapper = new AppMapper();
int checks=0;
void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS: "+name);}
var category=new Categoria{Id=7,Nombre="Anillos"};
var product=new Producto{Id=42,Nombre="REF/12",Precio=39.95,CategoriaId=7,Categoria=category,Descripcion="Oro",Eliminado=true,FechaEliminado=new DateTime(2026,10,1)};
category.Productos.Add(product);
product.Imagenes.Add(new(){Id="loaded-separately"});
var dto=mapper.Map<ProductoDto>(product);
Check(dto.Id==42&&dto.Nombre=="REF/12"&&dto.Precio==39.95&&dto.CategoriaNombre=="Anillos"&&dto.CategoriaId==7,"Referencia, precio y categoría conservados");
Check(dto.Eliminado&&dto.FechaEliminado==product.FechaEliminado,"Se conserva la visibilidad del producto");
Check(dto.Imagenes.Count==0&&dto.Tallas.Count==0&&dto.ProductoSeleccionadoId==null,"Imágenes y tallas se cargan por sus servicios");
Check(mapper.Map<ProductoDto>(new Producto()).CategoriaId==0&&mapper.Map<ProductoDto>(new Producto()).CategoriaNombre=="","Categoría ausente");
Check(mapper.Map<List<ProductoDto>>(new[]{product}).Single().Id==42&&mapper.Map<IEnumerable<ProductoDto>>(Array.Empty<Producto>()).Count()==0,"Listas y resultados vacíos");
Check(mapper.Map<ProductoDto>(null)==null,"Resultado ausente");
mapper.Map(new ProductoUpdateDto{Nombre="EDIT",Descripcion=null,Precio=55,CategoriaId=9},product);
Check(product.Id==42&&product.Eliminado&&product.FechaEliminado.HasValue&&product.Categoria==category,"Editar no altera identidad, baja ni relaciones");
Check(product.Nombre=="EDIT"&&product.Precio==55&&product.CategoriaId==9&&product.Descripcion==null,"Editar datos del producto");
Check(mapper.Map<Producto>(new ProductoCreateDto{Nombre="NEW",Precio=10,CategoriaId=7}).Nombre=="NEW","Alta de producto");
var user=new Usuario{Id=6,Email="cliente@example.invalid",Password="hash",Rol="USER"};
var order=new Pedido{Id=13,UsuarioId=6,Usuario=user,Estado=EstadoPedido.ENVIADO,Direccion=new(){Id=4,Calle="Mayor",Numero="2",UsuarioId=6}};
user.Pedidos.Add(order);
var line=new LineaPedido{Id=8,Pedido=order,Producto=product,ProductoId=42,Precio=19.95,Cantidad=3};order.LineasPedido.Add(line);
var od=mapper.Map<PedidoDto>(order);
Check(od.Total==59.849999999999994&&od.LineasPedido.Single().Subtotal==od.Total,"Totales según precio y unidades de las líneas, sin usar el precio actual");
Check(od.Estado=="ENVIADO"&&od.UsuarioEmail==user.Email&&od.Direccion?.Id==4&&od.LineasPedido[0].Producto?.Id==42,"Pedido con dirección, usuario y productos sin recursión por referencias circulares");
Check(mapper.Map<PedidoDto>(new Pedido()).Total==0&&mapper.Map<PedidoDto>(new Pedido()).Estado==null,"Pedido vacío y estado nulo");
var created=mapper.Map<Pedido>(new PedidoCreateDto{Direccion=new(){Calle="Nueva",Numero="1"}});
Check(created.Estado==EstadoPedido.PENDIENTE&&created.Direccion?.Calle=="Nueva"&&created.Fecha>=DateTime.Now.AddMinutes(-1)&&created.FechaEntregaEstimada>=DateTime.Now.AddDays(6),"Alta de pedido conserva fechas y estado inicial");
Check(mapper.Map<UsuarioDto>(user).CantidadPedidos==1,"Contador de pedidos");
Check(mapper.Map<Usuario>(new UsuarioCreateDto{Email=user.Email,Password="plain",Rol="USER"}).Password=="","El mapeo nunca copia contraseñas sin cifrar");
mapper.Map(new UsuarioUpdateDto{Email="edit@example.invalid",Password="plain",Rol="ADMIN"},user);
Check(user.Id==6&&user.Password=="hash"&&user.Email=="edit@example.invalid","Editar usuario conserva ID y hash");
Check(mapper.Map<CategoriaDto>(category).CantidadProductos==1,"Contador de productos sin recorrer ciclos");
mapper.Map(new CategoriaUpdateDto{Nombre="Nueva"},category);
Check(category.Id==7&&category.Productos.Count==1&&category.Nombre=="Nueva","Editar categoría conserva ID y productos");
Check(mapper.Map<Categoria>(new CategoriaCreateDto{Nombre="Relojes"}).Nombre=="Relojes","Alta de categoría");
var cart=new CarritoItem{Id=2,UsuarioId=6,ProductoId=42,Producto=product,Cantidad=2,Precio=8.50};
var cd=mapper.Map<CarritoItemDto>(cart);
Check(cd.Subtotal==17&&cd.Producto?.Id==42&&cd.ProductoNombre==product.Nombre,"Carrito conserva precio capturado y producto");
mapper.Map(new CarritoItemUpdateDto{Cantidad=4},cart);
Check(cart.Id==2&&cart.UsuarioId==6&&cart.ProductoId==42&&cart.Precio==8.50&&cart.Cantidad==4,"Editar carrito sólo cambia unidades");
Check(mapper.Map<CarritoItem>(new CarritoItemCreateDto{ProductoId=42,Cantidad=2}).ProductoId==42,"Alta de carrito");
var address=new Direccion{Id=4,UsuarioId=6,Calle="Antes"};
mapper.Map(new DireccionUpdateDto{Calle="Después",Numero="3",Piso=null,CodigoPostal="45200",Ciudad="Illescas",Provincia="Toledo"},address);
Check(address.Id==4&&address.UsuarioId==6&&address.Calle=="Después"&&address.Piso==null,"Editar dirección conserva titular e ID");
Check(mapper.Map<Direccion>(new DireccionCreateDto{Calle="Alta",Numero="5"}).Calle=="Alta"&&mapper.Map<DireccionDto>(address).UsuarioId==6,"Alta y consulta de direcciones");
Check(mapper.Map<LineaPedido>(new LineaPedidoCreateDto{PedidoId=13,ProductoId=42,Cantidad=2,Precio=6}).PedidoId==13,"Alta de línea de pedido");
var bytes=new byte[]{1,2,3,4};
var image=mapper.Map<ProductoImagenMongo>(new ProductoImagenCreateDto{ProductoId=42,ImagenData=bytes,TipoMime="image/png",EsPrincipal=true,Orden=2,NombreArchivo="foto.png"});
image.Id="507f1f77bcf86cd799439011";
Check(image.TamanoBytes==4&&image.ImagenData.SequenceEqual(bytes)&&image.FechaCreacion.Kind==DateTimeKind.Utc,"Alta de imagen conserva binario y fecha UTC");
var legacy=new BsonDocument{{"_id",ObjectId.Parse(image.Id)},{"producto_id",42L},{"imagen_data",new BsonBinaryData(bytes)},{"tipo_mime","image/png"},{"tamano_bytes",4},{"orden",2},{"es_principal",true},{"fecha_creacion",new BsonDateTime(image.FechaCreacion)},{"nombre_archivo","foto.png"}};
var restored=BsonSerializer.Deserialize<ProductoImagenMongo>(legacy);
var roundtrip=restored.ToBsonDocument();
Check(roundtrip.Equals(legacy),"MongoDB 3 conserva el esquema BSON anterior: ObjectId, Int64, binario y fecha");
var photo=mapper.Map<ProductoImagenDto>(restored);
Check(photo.Id==image.Id&&photo.ProductoId==42&&photo.EsPrincipal&&photo.Orden==2&&photo.ImagenBase64=="data:image/png;base64,AQIDBA==","Imagen de MongoDB lista para las vistas");
var message=new MimeMessage();message.From.Add(MailboxAddress.Parse("tienda@example.invalid"));message.To.Add(MailboxAddress.Parse("cliente@example.invalid"));message.Subject="Factura y confirmación — Alda Joyeros 1962";
var body=new BodyBuilder{HtmlBody="<p>Pedido confirmado: envío y dirección.</p>"};body.Attachments.Add("factura.pdf",System.Text.Encoding.ASCII.GetBytes("%PDF-1.4 test"),new ContentType("application","pdf"));message.Body=body.ToMessageBody();
using var stream=new MemoryStream();message.WriteTo(stream);stream.Position=0;var parsed=MimeMessage.Load(stream);
Check(parsed.Subject==message.Subject&&parsed.HtmlBody.Contains("dirección")&&parsed.Attachments.Single() is MimePart part&&part.FileName=="factura.pdf","MimeKit conserva asunto, HTML con acentos y factura adjunta sin enviar correo");
Console.WriteLine($"ALL {checks} CHECKS PASSED");
